 rarest_source &lt;- EIA_SEP_REPORT |&gt;
    count(primary_source) |&gt;
    slice_min(order_by = n, n = 1)

result &lt;- EIA_SEP_REPORT |&gt;
    filter(primary_source == rarest_source$primary_source) |&gt;
    select(primary_source, electricity_price_MWh, state, abbreviation)
    result

#My home state, Texas, has a reputation as being the home of “dirty fossil fuels” while NY has a reputation as a leader in clean energy. How many times cleaner is NY’s energy mix than that of Texas?
  tx_emissions &lt;- EIA_SEP_REPORT |&gt; 
                 filter(state == "Texas")|&gt;
                select(CO2_MWh)
                 tx_emissions

  ny_emissions &lt;- EIA_SEP_REPORT |&gt;
                filter(state =="New York")|&gt;
                select(CO2_MWh)
                ny_emissions

clean_ratio&lt;-tx_emissions/ ny_emissions
            round(clean_ratio, 2)

